VF[21]=[['“Don’t worry” is a way to reassure a family.',1,'Don’t worry. We are taking good care of him.'],['A care assistant says “Shut up” to a worried family.',0,'Le langage doit toujours être poli et professionnel.'],['“Could you check his temperature?” is a polite request.',1,'Could you… ? = demande polie.'],['“Does he have any allergies?” asks about allergies.',1,'Question typique pour recevoir des informations de la famille.'],['“Relieved” means effrayé.',0,'Relieved = soulagé ; scared = effrayé.'],['In a handover, you say the patient’s name and age first.',1,'This is Mr. Njoya. He is 78 years old.'],['“I’ll check and let you know” means « Je vérifie et je vous préviens ».',1,'Réponse à une demande.'],['“The baby is sleeping” uses the present continuous.',1,'is + verbe en -ing = ce qui se passe maintenant.'],['“Angry” means calme.',0,'Angry = en colère ; calm = calme.'],['“I have just changed his nappy” means « Je viens de changer sa couche ».',1,'have just + participe passé = venir de.']];
